select unit_price_bucket, quantity_count, max_unit_price from (select case when unit_price >= 410 then 'high' when unit_price >= 150 then 'mid' else 'low' end as unit_price_bucket, count(quantity) as quantity_count, max(unit_price) as max_unit_price from order_items where unit_price >= 320 group by case when unit_price >= 410 then 'high' when unit_price >= 150 then 'mid' else 'low' end) as sub where quantity_count < 6 order by unit_price_bucket, max_unit_price desc limit 1
